      pt: ["Fundação: 1954.", "Superfície: 410 km².", "Cascata mais alta: 20 metros.", "Elefantes estimados: 200 (2017).", "Distância de Juba: 200 km.", "Visitantes anuais: aprox. 500 (2019)."],
      fr: ["Fondation : 1954.", "Surface : 410 km².", "Cascade la plus haute : 20 mètres.", "Éléphants estimés : 200 (2017).", "Distance de Djouba : 200 km.", "Visiteurs annuels : env. 500 (2019)."],
